use crate::manifest::{load_all, root};
use crate::markers::{satisfies, verified};
use crate::resolve::resolve;
use anyhow::{bail, Result};
use std::collections::BTreeMap;
use std::fmt::Write as _;

pub const PHASE: &str = "P0 — Foundation";

fn status_md() -> Result<String> {
    let services = load_all()?;
    let mut s = String::new();
    writeln!(
        s,
        "<!-- @generated by `cargo xtask status`. DO NOT EDIT. -->"
    )?;
    writeln!(s, "# MCLE status\n")?;
    writeln!(s, "**Current phase:** {PHASE}.\n")?;
    writeln!(
        s,
        "Fidelity levels: L0 not implemented · L1 CRUD · L2 functional · L3 parity."
    )?;
    writeln!(
        s,
        "A ✔ means the declared level is backed by a test marker (`verifies(Lx): ...`).\n"
    )?;
    writeln!(s, "## Summary\n")?;
    writeln!(
        s,
        "| cloud | service | tier | facade | ops | L0 | L1 | L2 | L3 | test-backed |"
    )?;
    writeln!(s, "|---|---|---|---|---|---|---|---|---|---|")?;
    let mut detail = String::new();
    for e in &services {
        let r = resolve(e)?;
        let v = verified(e);
        let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
        let mut backed = 0;
        for op in &r.ops {
            *counts.entry(op.level.as_str()).or_default() += 1;
            if op.level == "L0" || satisfies(v.get(&op.name), &op.level) {
                backed += 1;
            }
        }
        let t = &e.toml.service;
        writeln!(
            s,
            "| {} | [{}](#{}-{}) | {} | {} | {} | {} | {} | {} | {} | {}/{} |",
            t.cloud,
            t.display,
            t.cloud,
            t.name,
            t.tier,
            t.facade,
            r.ops.len(),
            counts.get("L0").unwrap_or(&0),
            counts.get("L1").unwrap_or(&0),
            counts.get("L2").unwrap_or(&0),
            counts.get("L3").unwrap_or(&0),
            backed,
            r.ops.len()
        )?;
        writeln!(detail, "\n### {}-{}\n", t.cloud, t.name)?;
        writeln!(
            detail,
            "{} — `{}` — spec `{}` ({}, {} @ {}), protocol `{}`\n",
            t.display,
            e.crate_name(),
            t.api.spec,
            t.api.format,
            t.api.source,
            t.api.version,
            r.protocol
        )?;
        writeln!(
            detail,
            "| op | level | ✔ | IAM action | CRUD | LRO | plane |"
        )?;
        writeln!(detail, "|---|---|---|---|---|---|---|")?;
        for op in &r.ops {
            let ok = if op.level == "L0" {
                "—"
            } else if satisfies(v.get(&op.name), &op.level) {
                "✔"
            } else {
                "✘"
            };
            let crud = op
                .crud
                .as_ref()
                .map(|(t, v)| format!("{t}:{}", v.rust()))
                .unwrap_or_else(|| {
                    if op.custom {
                        "custom".into()
                    } else {
                        "—".into()
                    }
                });
            writeln!(
                detail,
                "| `{}` | {} | {} | `{}` | {} | {} | {} |",
                op.name, op.level, ok, op.iam_action, crud, op.lro, op.plane
            )?;
        }
    }
    writeln!(s, "\n## Not yet implemented (by phase)\n")?;
    writeln!(s, "- **P1:** generic L1 for all allowlisted specs; identity endpoints + metadata servers + CI OIDC; IAM control planes and evaluators; gRPC (tonic); TLS (`rustls`/`rcgen`); Terraform top-50 coverage (`coverage/terraform/`).")?;
    writeln!(s, "- **P2:** Tier-0 engines (object, queue, pubsub, log, kvdoc, secrets, kms, config, registry, telemetry, dns, mail, workflow), wire servers (Kafka, AMQP, OCI distribution, DNS), functions runtime.")?;
    writeln!(s, "- **P3:** CI/build integrations, `mcle tf`, seeding.")?;
    writeln!(s, "\n## Services\n{detail}")?;
    Ok(s)
}

fn codeowners() -> Result<String> {
    let mut s = String::from(
        "# @generated by `cargo xtask status` from service.toml owners. DO NOT EDIT.\n",
    );
    s.push_str("*                       @mcle/core\n/crates/                @mcle/core\n/engines/               @mcle/core\n/xtask/                 @mcle/core\n");
    for e in load_all()? {
        if e.toml.service.owners.is_empty() {
            continue;
        }
        let rel = e
            .dir
            .strip_prefix(root())
            .unwrap_or(&e.dir)
            .display()
            .to_string();
        writeln!(s, "/{rel}/ {}", e.toml.service.owners.join(" "))?;
    }
    Ok(s)
}

pub fn run(check: bool) -> Result<()> {
    let outputs = [
        (root().join("STATUS.md"), status_md()?),
        (root().join(".github").join("CODEOWNERS"), codeowners()?),
    ];
    let mut stale = Vec::new();
    for (p, text) in outputs {
        if std::fs::read_to_string(&p).unwrap_or_default() != text {
            if check {
                stale.push(p.display().to_string());
            } else {
                if let Some(d) = p.parent() {
                    std::fs::create_dir_all(d)?;
                }
                std::fs::write(&p, text)?;
                println!(
                    "status: wrote {}",
                    p.strip_prefix(root()).unwrap_or(&p).display()
                );
            }
        }
    }
    if !stale.is_empty() {
        bail!(
            "generated status files are stale (run `cargo xtask status`):\n  {}",
            stale.join("\n  ")
        );
    }
    Ok(())
}
